package com.zenitrade.controller;
import com.zenitrade.entity.User; import com.zenitrade.repository.UserRepository; import com.zenitrade.security.JwtService; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController { private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt;public AuthController(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;} public record Credentials(@NotBlank String name,@Email String email,@Size(min=6) String password){} public record Login(@Email String email,@NotBlank String password){} public record AuthResponse(String token,String name,String email){} @PostMapping("/register") public ResponseEntity<?> register(@RequestBody Credentials c){if(users.findByEmail(c.email().toLowerCase()).isPresent())return ResponseEntity.badRequest().body("Email already registered");User u=new User();u.name=c.name();u.email=c.email().toLowerCase();u.passwordHash=encoder.encode(c.password());users.save(u);return ResponseEntity.status(HttpStatus.CREATED).body(new AuthResponse(jwt.create(u.id,u.email),u.name,u.email));} @PostMapping("/login") public ResponseEntity<?> login(@RequestBody Login c){User u=users.findByEmail(c.email().toLowerCase()).orElse(null);if(u==null||!encoder.matches(c.password(),u.passwordHash))return ResponseEntity.status(401).body("Invalid email or password");return ResponseEntity.ok(new AuthResponse(jwt.create(u.id,u.email),u.name,u.email));} }
